#include "stdafx.h"#include <xmlhelper.h>namespace XMLHELPER{  MSXML::IXMLDOMElementPtr LoadXMLElement(const _variant_t & varSource, bstr_t bstrXPath)  {      // getting MSXML::IXMLDOMDocument interface      MSXML::IXMLDOMDocumentPtr xmlDoc;      xmlDoc.CreateInstance(__uuidof(MSXML::DOMDocument));      if (xmlDoc != NULL)      {          // loading configuration file into the parser          if (xmlDoc->load(varSource) != VARIANT_FALSE)          {              // getting root element              MSXML::IXMLDOMElementPtr xmlRoot = xmlDoc->GetdocumentElement();              if (xmlRoot != NULL)              {                  if (bstrXPath.length() == 0)                      return xmlRoot;                  else                      return xmlRoot->selectSingleNode(bstrXPath);              }          }      }      return NULL;  }  MSXML::IXMLDOMElementPtr LoadXMLElementFromString(bstr_t bstrString, bstr_t bstrXPath)  {      // getting MSXML::IXMLDOMDocument interface      MSXML::IXMLDOMDocumentPtr xmlDoc;      xmlDoc.CreateInstance(__uuidof(MSXML::DOMDocument));      if (xmlDoc != NULL)      {          // loading configuration file into the parser          if (xmlDoc->loadXML(bstrString) != VARIANT_FALSE)          {              // getting root element              MSXML::IXMLDOMElementPtr xmlRoot = xmlDoc->documentElement;              if (xmlRoot != NULL)              {                  if (bstrXPath.length() == 0)                      return xmlRoot;                  else                      return xmlRoot->selectSingleNode(bstrXPath);              }          }      }      return NULL;  }  //  // FUNCTION: bool CheckXMLElementAttribute(const MSXML::IXMLDOMElementPtr& xml, LPCWSTR szAttrName, LPCTSTR szTest = L"yes|on")  // PURPOSE :  //  bool CheckXMLElementAttribute(const MSXML::IXMLDOMElementPtr& xml, LPCWSTR szAttrName, LPCSTR szTest)  {      if (xml == NULL)          return szTest == NULL;      variant_t varAttr = xml->getAttribute(_bstr_t(szAttrName));      if (varAttr.vt != VT_BSTR || szTest == NULL)          return (varAttr.vt != VT_BSTR) == (szTest == NULL);      _bstr_t bstrAttr = varAttr;      LPCTSTR sz = szTest - 1;      do      {          sz++;          if (*sz == '|' || *sz == 0)          {              if (_strnicmp(szTest, (LPCTSTR)bstrAttr, sz - szTest) == 0)                  return true;              if (*sz == '|')                  szTest = ++sz;          }      } while(*sz != 0);      return false;  }  ///////////////////////////////////////////////////////////////////////////////  void beautify_xml_node(MSXML::IXMLDOMNodePtr xmlNode, const _bstr_t& strLevelIndent, const _bstr_t& strCurIndent)  {      static int iCounter;      //Если узел дочерний, то ничего не делаем:      if (! xmlNode->hasChildNodes()) return;      //Если содержимое узла содержит текстовые узлы,       //то ничего не делаем:      MSXML::IXMLDOMNodePtr xmlChildNode = xmlNode->firstChild;      while (xmlChildNode != NULL)      {          if (xmlChildNode->nodeType == NODE_TEXT) //CDATA          {              if (xmlChildNode != NULL) return;          }          //Переход к следующему соседу (по родительскому узлу,          //к соседу с одинаковым уровнем по дереву):          xmlChildNode = xmlChildNode->nextSibling;      }      //Создание текстового узла-разделителя:      MSXML::IXMLDOMNodePtr xmlTextNode =           xmlNode->ownerDocument->createNode(NODE_TEXT, L"", L"");      //Формирование нового отступа-разделителя:      _bstr_t strNewIndent = strCurIndent + strLevelIndent;      //Установка текста для узла-разделителя:      xmlTextNode->text = strNewIndent;      //Перебор дочерних узлов по дереву:      xmlChildNode = xmlNode->firstChild;      while (xmlChildNode != NULL)      {          //Вставка текстовых узлов-разделителей с отступами          //между существующими дочерними узлами          xmlNode->insertBefore(xmlTextNode->cloneNode(false),               (MSXML::IXMLDOMNode *)xmlChildNode);          //Рекурсия (для текущего узла):          beautify_xml_node(xmlChildNode, strLevelIndent, strNewIndent);          //Переход к следующему соседу (по родительскому узлу,          //к соседу с одинаковым уровнем по дереву):                  xmlChildNode = xmlChildNode->nextSibling;      }      //Установка текста для узла-разделителя:      xmlTextNode->text = strCurIndent;      //Добавление узла-разделителя в дерево документа:       xmlNode->appendChild(xmlTextNode);  }}